package com.headunit.launcher

/**
 * Hand-written (not made by tr/genlang.py, so a regenerate won't lose them): what's said when the OpenStreetMap map (OpenFreeMap's
 * tiles) doesn't appear (#464). Order: the server answers badly, it answers but nothing is drawn, it can't be reached.
 */
internal object I18nOsmCheck {
    private val keys = listOf(
        "OpenFreeMap's map server isn't answering properly from this device. Try again later, or switch the map to Mapbox in Settings › Map.",
        "OpenFreeMap answers, but the map isn't drawing on this device. Please send a report from Settings › Feedback so it can be looked into.",
        "This device can't reach OpenFreeMap's map server. Check the internet connection: a private DNS, ad blocker or firewall may be blocking tiles.openfreemap.org."
    )

    private val t: Map<String, List<String>> = mapOf(
        "nl" to listOf("De kaartserver van OpenFreeMap antwoordt niet goed vanaf dit apparaat. Probeer het later opnieuw, of schakel de kaart naar Mapbox in Instellingen › Kaart.", "OpenFreeMap antwoordt, maar de kaart wordt niet getekend op dit apparaat. Stuur een melding via Instellingen › Feedback zodat het kan worden uitgezocht.", "Dit apparaat kan de kaartserver van OpenFreeMap niet bereiken. Controleer de internetverbinding: een privé-DNS, adblocker of firewall blokkeert misschien tiles.openfreemap.org."),
        "de" to listOf("Der Kartenserver von OpenFreeMap antwortet von diesem Gerät aus nicht richtig. Versuche es später erneut oder stelle die Karte unter Einstellungen › Karte auf Mapbox um.", "OpenFreeMap antwortet, aber die Karte wird auf diesem Gerät nicht gezeichnet. Bitte sende eine Meldung über Einstellungen › Feedback, damit es untersucht werden kann.", "Dieses Gerät erreicht den Kartenserver von OpenFreeMap nicht. Prüfe die Internetverbindung: Ein privater DNS, Werbeblocker oder eine Firewall blockiert vielleicht tiles.openfreemap.org."),
        "fr" to listOf("Le serveur de cartes d'OpenFreeMap ne répond pas correctement depuis cet appareil. Réessayez plus tard, ou passez la carte à Mapbox dans Réglages › Carte.", "OpenFreeMap répond, mais la carte ne s'affiche pas sur cet appareil. Envoyez un rapport depuis Réglages › Commentaires pour qu'on regarde.", "Cet appareil ne peut pas joindre le serveur de cartes d'OpenFreeMap. Vérifiez la connexion : un DNS privé, un bloqueur de publicités ou un pare-feu bloque peut-être tiles.openfreemap.org."),
